const body = $('Webhook').first().json.body;

const options = {};
if (body.temperature != null) options.temperature = body.temperature;
if (body.max_tokens != null) options.num_predict = body.max_tokens;
const model = body.model || $env.OLLAMA_MODEL || 'llama3.1';

const system = [
  'You triage customer support tickets.',
  'Answer with one JSON object and nothing else:',
  '{"category": "billing" | "bug" | "account" | "question" | "other",',
  ' "priority": "low" | "normal" | "high" | "urgent",',
  ' "reply": "a short, polite first reply to the customer, in the language of the ticket"}',
].join('\n');

return [{ json: {
  model, stream: false, format: 'json', options,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: String(body.prompt ?? '') },
  ],
} }];
